commit.command:
cd "$(pwd)" && git commit -m "$(cat <<'EOF'
release(alpha): bump version reference to v0.2.0

Co-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>
EOF
)" && git --no-optional-locks rev-parse HEAD HEAD^{tree}

git commit -m "$(cat <<'EOF'
chore(alpha): update version references for v0.2.0

Co-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>
EOF
)"
git --no-optional-locks rev-parse HEAD HEAD^{tree}

cd "$(git rev-parse --show-toplevel)" && git commit -m "$(cat <<'EOF'
chore(alpha): bump version reference to v0.2.0

Co-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>
EOF
)" && git --no-optional-locks rev-parse HEAD HEAD^{tree}

